int calculerSommeChiffres(int n)
{
    int somme = 0;
    while (n > 0)
    {
        somme = somme + n % 10;
        n = n / 10;
    }
    return somme;
}

int main()
{
    cout << calculerSommeChiffres(472) << '\n';
    cout << calculerSommeChiffres(2025) << '\n';
}

